import photos from "./photos.json";

// "/things" in production, "" when served from a root. Vite substitutes BASE_URL at build.
const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");

// All copy for the page lives here, transcribed verbatim from content.md — the one
// exception is the Museums chapter, marked `draft` below, which content.md has no text for.
//
// A chapter holds `groups`. Most have one, which renders as a single unlabelled strip;
// Make and Explore have several, each labelled. Quiet chapters have none. `key` matches a
// bucket in photos.json, which is generated by `npm run photos` from scripts/photo-map.js.

// The page deliberately says nothing about why there was time for any of this. It is a list
// of things done, not an account of a period.
//
// `quote` / `attribution` are kept but NOT currently rendered — the markup that showed them
// in the footer is commented out in welcome.jsx. Uncomment that block to bring them back.
export const intro = {
  title: "Things I've been up to",
  paragraphs: [
    "By day I'm a developer. Outside of that, this is the fun stuff — some I've done forever, some I just started.",
  ],
  quote: "I don't know where I'm going from here, but I promise it won't be boring.",
  attribution: "David Bowie",
};

// The name appears nowhere on the page itself — only in the tab title.
export const closing = {
  // The address is never printed — it hides behind `emailLabel`, which becomes the link.
  invitation: "If you'd like to get in touch,",
  emailLabel: "email me",
  // Plus-addressed so mail from the site can be filtered. Emptying this string hides the
  // whole invitation line rather than shipping a dead address.
  email: "natashatarn+blog@gmail.com",
  link: {
    href: "https://tarnopolsky.github.io",
    label: "My professional résumé",
  },
};

